import json

questions = json.loads(r'''[
{"topic":"Foundations of AI","type":"MCQ","difficulty":"Easy","question":"A hospital uses a system that analyses symptoms and suggests possible diagnoses. Which AI capability is most directly demonstrated?","options":["Natural language translation","Reasoning and decision support","Game-tree search","Robot motion control"],"answer":"Reasoning and decision support","hint":"Consider how the system uses information to reach a conclusion.","explanation":"The system reasons from patient information to support a decision.","id":"Q01"},
{"topic":"Foundations of AI","type":"Assertion–Reason","difficulty":"Easy","question":"Assertion (A): AI research includes systems that reason and systems that act. Reason (R): Every AI system must have a physical robot body.","options":["Both A and R are true, and R explains A","Both A and R are true, but R does not explain A","A is true, but R is false","A is false, but R is true"],"answer":"A is true, but R is false","hint":"Think of a chatbot or chess program.","explanation":"AI includes reasoning and acting systems, but an AI system does not need a physical body.","id":"Q02"},
{"topic":"Turing Test","type":"MCQ","difficulty":"Easy","question":"In the standard Turing Test, what is the evaluator primarily trying to determine?","options":["Whether a machine has a physical body","Whether a machine can be distinguished from a human through conversation","Whether a machine can solve every mathematical problem","Whether a machine has emotions"],"answer":"Whether a machine can be distinguished from a human through conversation","hint":"The test is based on responses in a conversation.","explanation":"The evaluator judges whether the machine's conversational behaviour is distinguishable from a human's.","id":"Q03"},
{"topic":"Intelligent Agents","type":"MCQ","difficulty":"Easy","question":"Which sequence correctly describes an agent's interaction with its environment?","options":["Actuators receive percepts; sensors perform actions","Sensors receive percepts; actuators carry out actions","The environment selects the agent's goals","The agent acts without receiving any information"],"answer":"Sensors receive percepts; actuators carry out actions","hint":"Separate information gathering from action.","explanation":"Sensors provide percepts, while actuators allow an agent to act on its environment.","id":"Q04"},
{"topic":"Rational Agents","type":"Scenario","difficulty":"Easy","question":"A delivery robot chooses a route that maximises expected successful deliveries while considering traffic and battery level. This is best described as:","options":["Random behaviour","Rational action based on available information","A guaranteed optimal action in every possible world","Uninformed search only"],"answer":"Rational action based on available information","hint":"Rationality concerns expected performance, not perfect knowledge.","explanation":"A rational agent selects actions expected to perform well given its percepts and available knowledge.","id":"Q05"},
{"topic":"Rational Agents","type":"MCQ","difficulty":"Easy","question":"Which statement about a rational agent is correct?","options":["It always knows the future","It always chooses the same action in every situation","It selects actions expected to maximise its performance measure","It must learn from every action"],"answer":"It selects actions expected to maximise its performance measure","hint":"Focus on the performance measure.","explanation":"Rationality is defined relative to the performance measure and information available to the agent.","id":"Q06"},
{"topic":"Agents and Environments","type":"Match the Following","difficulty":"Easy","question":"Match the agent component to its role: sensors, actuators, performance measure.","options":["Sensors—measure success; actuators—receive percepts; performance measure—moves the agent","Sensors—receive percepts; actuators—perform actions; performance measure—evaluates success","Sensors—perform actions; actuators—evaluate success; performance measure—stores percepts","All three perform the same function"],"answer":"Sensors—receive percepts; actuators—perform actions; performance measure—evaluates success","hint":"Each component has a distinct role.","explanation":"Sensors gather information, actuators produce actions, and the performance measure specifies success.","id":"Q07"},
{"topic":"Nature of Environments","type":"MCQ","difficulty":"Easy","question":"A chess-playing agent can observe the complete board before making a move. In the standard formulation, chess is:","options":["Partially observable","Fully observable","Unknown and continuous only","Episodic and single-state"],"answer":"Fully observable","hint":"Can the agent see all pieces and their positions?","explanation":"The board state is available to both players, so the environment is fully observable.","id":"Q08"},
{"topic":"Nature of Environments","type":"Scenario","difficulty":"Easy","question":"A self-driving car must react to moving vehicles, uncertain pedestrian behaviour, and changing road conditions. Which environment property is especially relevant?","options":["Static","Deterministic and fully predictable","Dynamic and uncertain","Single-state"],"answer":"Dynamic and uncertain","hint":"The environment changes while the car is operating.","explanation":"Road environments are dynamic and involve uncertainty because other agents and conditions change.","id":"Q09"},
{"topic":"Problem Formulation","type":"Scenario","difficulty":"Easy","question":"A route-finding program must travel from Bengaluru to Mysuru at minimum travel cost. Which option is a suitable goal test?","options":["The current city has the largest population","The route contains at least five roads","The current state is Mysuru","The heuristic value is always zero"],"answer":"The current state is Mysuru","hint":"A goal test checks whether the desired destination has been reached.","explanation":"The goal test determines whether the current state satisfies the destination requirement.","id":"Q10"},
{"topic":"Problem Spaces","type":"MCQ","difficulty":"Easy","question":"In a state-space formulation of a problem, what does an action or operator usually represent?","options":["A rule that transforms one state into a successor state","The final answer only","The performance measure of every AI system","A random evaluation score"],"answer":"A rule that transforms one state into a successor state","hint":"Think about how one state becomes another.","explanation":"Operators describe available transitions between states.","id":"Q11"},
{"topic":"Problem Formulation","type":"MCQ","difficulty":"Easy","question":"A well-defined search problem typically specifies:","options":["Only a starting state","Initial state, actions, transition model, goal test, and path cost","Only a heuristic function","Only the number of possible solutions"],"answer":"Initial state, actions, transition model, goal test, and path cost","hint":"A search problem needs a start, legal moves, a goal, and a cost model.","explanation":"These components define the problem that a search algorithm must solve.","id":"Q12"},
{"topic":"Production Systems","type":"MCQ","difficulty":"Easy","question":"In a rule-based production system, a production rule is commonly written as:","options":["IF condition THEN action","START THEN STOP only","INPUT = OUTPUT always","STATE < COST"],"answer":"IF condition THEN action","hint":"Think of condition-action rules.","explanation":"Production systems use rules whose conditions determine which actions can be applied.","id":"Q13"},
{"topic":"Breadth-First Search","type":"MCQ","difficulty":"Easy","question":"Which data structure is normally used to implement breadth-first search?","options":["Stack","Queue","Priority queue ordered by heuristic only","Hash function only"],"answer":"Queue","hint":"BFS expands the oldest waiting node first.","explanation":"A FIFO queue ensures that nodes are expanded in order of increasing depth.","id":"Q14"},
{"topic":"Breadth-First Search","type":"Search Problem","difficulty":"Easy","question":"A tree has root S, children A and B; A has children C and D; B has children E and F. With left-to-right expansion, what is the BFS order?","options":["S, A, C, D, B, E, F","S, B, A, F, E, D, C","S, A, B, C, D, E, F","S, C, D, A, E, F, B"],"answer":"S, A, B, C, D, E, F","hint":"BFS completes each depth level before moving deeper.","explanation":"BFS visits S, then A and B, then C, D, E, and F.","id":"Q15"},
{"topic":"Breadth-First Search","type":"MCQ","difficulty":"Easy","question":"Under the usual assumptions of equal step costs and finite branching, which statement about BFS is correct?","options":["It is complete and finds a shallowest solution","It always uses less memory than DFS","It always finds the lowest-cost solution when step costs differ","It expands only the deepest node"],"answer":"It is complete and finds a shallowest solution","hint":"BFS explores by depth, not by arbitrary path cost.","explanation":"BFS is complete under standard conditions and finds a shallowest goal; it is not generally optimal for unequal step costs.","id":"Q16"},
{"topic":"Depth-First Search","type":"MCQ","difficulty":"Easy","question":"Which data structure best matches the standard depth-first search strategy?","options":["FIFO queue","LIFO stack","Sorted list by path cost only","Circular queue with no backtracking"],"answer":"LIFO stack","hint":"DFS explores one branch deeply before backtracking.","explanation":"A stack or recursive call structure supports last-in, first-out exploration.","id":"Q17"},
{"topic":"Depth-First Search","type":"Search Problem","difficulty":"Easy","question":"Using left-to-right child order, DFS explores S; S has children A and B; A has children C and D. What is the order until C is first visited?","options":["S, B, A, D, C","S, A, C","S, A, D, B, C","S, C, A"],"answer":"S, A, C","hint":"Follow the left branch as far as possible.","explanation":"DFS visits S, moves to A, and then visits A's left child C.","id":"Q18"},
{"topic":"DFS and BFS","type":"Assertion–Reason","difficulty":"Easy","question":"Assertion (A): DFS often uses less memory than BFS on a wide search tree. Reason (R): DFS generally stores the current path and unexplored alternatives rather than an entire broad frontier.","options":["Both A and R are true, and R explains A","Both A and R are true, but R does not explain A","A is true, but R is false","Both A and R are false"],"answer":"Both A and R are true, and R explains A","hint":"Think about how many frontier nodes each algorithm may store.","explanation":"BFS can store a very large frontier, while DFS typically retains a path and pending alternatives.","id":"Q19"},
{"topic":"Iterative Deepening","type":"MCQ","difficulty":"Easy","question":"What does iterative deepening depth-first search do?","options":["Uses BFS once and stops","Runs depth-limited DFS repeatedly with increasing depth limits","Selects only nodes with the smallest heuristic","Expands nodes in decreasing path cost"],"answer":"Runs depth-limited DFS repeatedly with increasing depth limits","hint":"The depth limit changes from one iteration to the next.","explanation":"IDDFS repeats depth-limited searches at limits 0, 1, 2, and so on.","id":"Q20"},
{"topic":"Iterative Deepening","type":"Scenario","difficulty":"Easy","question":"The depth of the solution is unknown, memory is limited, and every step has equal cost. Which search strategy is often a useful choice?","options":["Iterative deepening DFS","Greedy best-first search without a heuristic","Hill climbing only","Random walk without a stopping rule"],"answer":"Iterative deepening DFS","hint":"Combine the shallow-solution benefit with DFS-like memory use.","explanation":"IDDFS is complete under standard conditions, finds a shallowest solution with equal step costs, and uses relatively little memory.","id":"Q21"},
{"topic":"Heuristic Search","type":"MCQ","difficulty":"Easy","question":"What does a heuristic function h(n) estimate in a goal-directed search problem?","options":["The exact cost already paid from the start","The remaining cost or distance from node n to a goal","The number of actions already performed","The total number of states in every possible problem"],"answer":"The remaining cost or distance from node n to a goal","hint":"It estimates what remains, not what has already happened.","explanation":"A heuristic estimates the cost of reaching a goal from the current state.","id":"Q22"},
{"topic":"Best-First Search","type":"MCQ","difficulty":"Easy","question":"Greedy best-first search usually selects the frontier node with the smallest:","options":["Depth only","Heuristic estimate h(n)","Accumulated path cost g(n) only","Number of ancestors"],"answer":"Heuristic estimate h(n)","hint":"Greedy best-first search prioritises estimated distance to the goal.","explanation":"Its evaluation function is f(n) = h(n), unlike A* which uses g(n) + h(n).","id":"Q23"},
{"topic":"Best-First Search","type":"Search Problem","difficulty":"Easy","question":"The frontier contains A with h(A)=7, B with h(B)=2, and C with h(C)=5. Which node does greedy best-first search select next?","options":["A","B","C","It must select the shallowest node"],"answer":"B","hint":"Choose the lowest heuristic estimate.","explanation":"B has the smallest heuristic value, 2.","id":"Q24"},
{"topic":"Heuristic Search","type":"MCQ","difficulty":"Easy","question":"Suppose h(n) never overestimates the true minimum remaining cost to the goal. This heuristic is called:","options":["Inconsistent by definition","Admissible","Random","A production rule"],"answer":"Admissible","hint":"An admissible heuristic is optimistic about remaining cost.","explanation":"Admissibility means the heuristic does not overestimate the optimal remaining cost.","id":"Q25"}
]''')

questions_part_2 = json.loads(r'''[
{"topic":"Hill Climbing","type":"MCQ","difficulty":"Easy","question":"Hill climbing typically chooses a neighbouring state that:","options":["Improves the evaluation value compared with the current state","Is always the first state alphabetically","Has the greatest depth regardless of quality","Has already been visited most often"],"answer":"Improves the evaluation value compared with the current state","hint":"It makes a local move based on the evaluation function.","explanation":"Hill climbing repeatedly moves to a better neighbouring state according to its evaluation.","id":"Q26"},
{"topic":"Hill Climbing","type":"Scenario","difficulty":"Easy","question":"A hill-climbing algorithm stops because all neighbouring states have the same evaluation as the current state, but a better solution exists elsewhere. This illustrates:","options":["A guaranteed global optimum","A local plateau or local-search limitation","A successful BFS traversal","A fully observable environment"],"answer":"A local plateau or local-search limitation","hint":"The algorithm may be unable to find an improving local move.","explanation":"Plateaus and local optima can prevent basic hill climbing from reaching a global optimum.","id":"Q27"},
{"topic":"Hill Climbing","type":"MCQ","difficulty":"Easy","question":"Which method helps basic hill climbing reduce the risk of becoming trapped in one local optimum by restarting from different initial states?","options":["Random-restart hill climbing","Breadth-first search with no queue","A fixed depth limit","Removing the evaluation function"],"answer":"Random-restart hill climbing","hint":"The method changes the starting point.","explanation":"Random restarts allow hill climbing to explore different regions of the state space.","id":"Q28"},
{"topic":"Local Search","type":"MCQ","difficulty":"Easy","question":"Which statement best describes simulated annealing compared with basic hill climbing?","options":["It can sometimes accept a worse move to escape local traps","It never evaluates neighbouring states","It guarantees the first state is optimal","It is identical to BFS"],"answer":"It can sometimes accept a worse move to escape local traps","hint":"Occasional non-improving moves can help exploration.","explanation":"Simulated annealing may accept worse moves, especially early in the process, to escape local optima.","id":"Q29"},
{"topic":"Constraint Satisfaction Problems","type":"MCQ","difficulty":"Easy","question":"Which set of components defines a constraint satisfaction problem (CSP)?","options":["Variables, domains, and constraints","Sensors, actuators, and performance measure","Root, queue, and heuristic only","Training set, test set, and loss function"],"answer":"Variables, domains, and constraints","hint":"A CSP specifies what must be assigned and which assignments are allowed.","explanation":"Variables take values from domains while satisfying the problem's constraints.","id":"Q30"},
{"topic":"CSP","type":"Scenario","difficulty":"Easy","question":"Three neighbouring regions must be coloured so that no two neighbours share a colour. What is the constraint?","options":["Each region must use every colour","Neighbouring regions must have different colours","Every region must use the same colour","Regions cannot be variables"],"answer":"Neighbouring regions must have different colours","hint":"The restriction applies between neighbouring regions.","explanation":"The constraint rules out equal colours for adjacent regions.","id":"Q31"},
{"topic":"CSP","type":"Problem Solving","difficulty":"Easy","question":"A CSP variable X has domain {red, blue, green}. A constraint rules out blue and green for X. What remains in X's domain?","options":["{blue, green}","{red}","{red, blue}","The empty set"],"answer":"{red}","hint":"Remove every value disallowed by the constraint.","explanation":"Only red remains after blue and green are eliminated.","id":"Q32"},
{"topic":"CSP","type":"MCQ","difficulty":"Easy","question":"In a CSP, the minimum-remaining-values (MRV) heuristic chooses the unassigned variable with:","options":["The largest domain","The fewest legal values remaining","The highest alphabetical position","The most expensive value"],"answer":"The fewest legal values remaining","hint":"MRV focuses on the most constrained variable.","explanation":"Choosing the variable with the fewest remaining values can reveal failure early.","id":"Q33"},
{"topic":"CSP","type":"MCQ","difficulty":"Easy","question":"What is the main purpose of constraint propagation?","options":["To remove domain values that cannot participate in a valid solution","To add arbitrary values to every domain","To turn a CSP into an image classifier","To ignore constraints until the end"],"answer":"To remove domain values that cannot participate in a valid solution","hint":"Propagation uses constraints to narrow possible assignments.","explanation":"Constraint propagation reduces domains by enforcing consequences of constraints.","id":"Q34"},
{"topic":"Means-End Analysis","type":"MCQ","difficulty":"Easy","question":"In means-end analysis, what does a problem solver generally do when the current state differs from the goal state?","options":["Identifies a difference and selects an operator that can reduce it","Chooses an action without considering the goal","Restarts every time it encounters a state","Uses only alphabetical ordering"],"answer":"Identifies a difference and selects an operator that can reduce it","hint":"Compare the current state with the desired state.","explanation":"Means-end analysis identifies differences between current and goal states and chooses operators to reduce them.","id":"Q35"},
{"topic":"Means-End Analysis","type":"Scenario","difficulty":"Easy","question":"A robot must move a box onto a high shelf. The box is on the floor and the robot cannot reach the shelf. It first needs to move a ladder into position. This is an example of:","options":["Creating a subgoal to overcome a difference between the current state and goal","A goal test failing permanently","Breadth-first traversal only","A rational agent ignoring its environment"],"answer":"Creating a subgoal to overcome a difference between the current state and goal","hint":"The ladder is an intermediate step needed to achieve the final goal.","explanation":"Means-end analysis can create subgoals when an operator's preconditions are not yet satisfied.","id":"Q36"},
{"topic":"Real-World Applications","type":"Scenario","difficulty":"Easy","question":"A warehouse robot repeatedly senses shelf locations, updates its internal state, and moves to collect an item. Which description fits best?","options":["A perception-action agent","A static lookup table with no inputs","A CSP with no variables","A Turing Test evaluator"],"answer":"A perception-action agent","hint":"The robot observes and then acts.","explanation":"The robot uses percepts to guide actions in its environment.","id":"Q37"},
{"topic":"Real-World Applications","type":"Scenario","difficulty":"Easy","question":"A timetable generator assigns classes to rooms and time slots while avoiding clashes between classes. Which AI formulation is especially suitable?","options":["Constraint satisfaction problem","Unrestricted random search only","Turing Test","Simple reflex action with no constraints"],"answer":"Constraint satisfaction problem","hint":"The task involves assignments that must satisfy restrictions.","explanation":"Timetabling can be represented as variables, domains, and constraints.","id":"Q38"},
{"topic":"Real-World Applications","type":"Scenario","difficulty":"Easy","question":"A game-playing agent evaluates possible moves and explores future game states before choosing a move. Which AI idea is most directly involved?","options":["State-space search","Data encryption only","Image compression","Episodic classification only"],"answer":"State-space search","hint":"The agent explores possible future states.","explanation":"Game-playing systems can search a state space of possible moves and resulting positions.","id":"Q39"},
{"topic":"Real-World Applications","type":"Scenario","difficulty":"Easy","question":"A customer-support system applies IF-THEN rules to route a request to billing, technical support, or account recovery. Which approach is most directly illustrated?","options":["Production system","Hill climbing without an evaluation","Depth-limited search only","Fully random action selection"],"answer":"Production system","hint":"Look for condition-action rules.","explanation":"Rule-based routing uses conditions to trigger actions or decisions.","id":"Q40"},
{"topic":"Real-World Applications","type":"Scenario","difficulty":"Easy","question":"A smart thermostat observes the room temperature and activates heating when the temperature falls below its target. Which concept best describes this behaviour?","options":["An agent perceiving and acting on an environment","A state space with no actions","A Turing Test conversation","A CSP with no constraints"],"answer":"An agent perceiving and acting on an environment","hint":"It senses a condition and takes an action.","explanation":"The thermostat receives sensor input and acts through a heating control mechanism.","id":"Q41"},
{"topic":"Real-World Applications","type":"Scenario","difficulty":"Moderate","question":"A delivery planner compares routes by total distance already travelled plus an estimate of the remaining distance. Which search evaluation does this resemble?","options":["f(n) = g(n) + h(n)","f(n) = h(n) only","f(n) = depth only","f(n) = number of variables only"],"answer":"f(n) = g(n) + h(n)","hint":"One term is the cost so far; the other estimates the cost remaining.","explanation":"A* search combines the accumulated path cost g(n) and heuristic estimate h(n).","id":"Q42"},
{"topic":"Search Algorithms","type":"Problem Solving","difficulty":"Moderate","question":"A graph has edges S–A (cost 2), S–B (cost 1), A–G (cost 2), and B–G (cost 8). Which route has the lowest total cost?","options":["S–A–G, cost 4","S–B–G, cost 9","Both routes cost 4","Neither route reaches G"],"answer":"S–A–G, cost 4","hint":"Add the edge costs along each route.","explanation":"The S–A–G route costs 2 + 2 = 4, while S–B–G costs 1 + 8 = 9.","id":"Q43"},
{"topic":"Search Algorithms","type":"Problem Solving","difficulty":"Moderate","question":"A tree has root S with children A and B. A has children C and G; B has child H. If BFS examines children left to right, which goal is found first?","options":["C","G","H","S"],"answer":"G","hint":"BFS visits nodes level by level and checks the nodes at depth 2 from left to right.","explanation":"After S, A, and B, BFS checks C and then G before reaching H.","id":"Q44"},
{"topic":"Search Algorithms","type":"Problem Solving","difficulty":"Moderate","question":"A search algorithm expands the node with the smallest accumulated path cost g(n). Which algorithm does this describe?","options":["Uniform-cost search","Greedy best-first search","Hill climbing","Depth-limited DFS"],"answer":"Uniform-cost search","hint":"This strategy prioritises the cost already paid.","explanation":"Uniform-cost search expands the frontier node with the lowest path cost g(n).","id":"Q45"},
{"topic":"Search Algorithms","type":"Assertion–Reason","difficulty":"Easy","question":"Assertion (A): Greedy best-first search is guaranteed to find the least-cost solution in every search problem. Reason (R): It selects nodes using only the heuristic estimate h(n).","options":["Both A and R are true, and R explains A","Both A and R are true, but R does not explain A","A is true, but R is false","A is false, but R is true"],"answer":"A is false, but R is true","hint":"Greedy best-first search does not directly account for the cost already paid.","explanation":"The assertion is false: greedy best-first uses h(n) and is not generally optimal. The reason is true.","id":"Q46"},
{"topic":"Problem Spaces","type":"Fill in the Blank","difficulty":"Easy","question":"The set of states reachable from the initial state by applying legal operators forms the reachable ______ of the problem.","options":["state space","performance measure","sensor array","training label"],"answer":"state space","hint":"It describes the states and transitions that search can explore.","explanation":"The state space represents possible states and the transitions between them.","id":"Q47"},
{"topic":"Turing Test","type":"True/False","difficulty":"Easy","question":"Passing the standard Turing Test proves that a machine has consciousness.","options":["True","False"],"answer":"False","hint":"The test evaluates observable conversational behaviour.","explanation":"The Turing Test concerns whether behaviour is distinguishable from a human's; it does not prove consciousness.","id":"Q48"},
{"topic":"Agents and Environments","type":"True/False","difficulty":"Easy","question":"A rational agent can make a reasonable decision even when it does not have complete information about the environment.","options":["True","False"],"answer":"True","hint":"Rationality is based on the information available to the agent.","explanation":"Rational decisions depend on percepts, knowledge, available actions, and the performance measure.","id":"Q49"},
{"topic":"Search Algorithms","type":"True/False","difficulty":"Easy","question":"Depth-first search is guaranteed to find a shallowest solution in every finite search tree.","options":["True","False"],"answer":"False","hint":"DFS explores depth before breadth.","explanation":"DFS may find a deeper goal before a shallower one because it follows one branch deeply.","id":"Q50"}
]''')

questions.extend(questions_part_2)

assert len(questions) == 50, f"Expected 50 questions, found {len(questions)}"